     * 与同案件证物的销毁互斥；requestId 全局唯一，同键换案件/到期时间/原因返回 409。
     */
    @Transactional
    public StoredResponse placeCaseHold(actorId: String, String caseKey,
                                        HoldCreateRequest request, String requestHash) {
        throw new UnsupportedOperationException();
    }
}

